(5, 8, '_messages', 'a:21:{s:12:\"mail_sent_ok\";s:53:\"تم إرسال الرسالة بنجاح. شكراً\";s:12:\"mail_sent_ng\";s:200:\"فشل في إرسال الرسالة. الرجاء المحاولة مجدداً أو مخاطبة المسؤول عن الموقع بطريقة أخرى مثل الفيس بوك أو التويتر.\";s:16:\"validation_error\";s:126:\"حدث خطأ أثناء التحقق. الرجاء التأكد من الحقول ومعاودة الإرسال مجدداً.\";s:4:\"spam\";s:200:\"فشل في إرسال الرسالة. الرجاء المحاولة مجدداً أو مخاطبة المسؤول عن الموقع بطريقة أخرى مثل الفيس بوك أو التويتر.\";s:12:\"accept_terms\";s:80:\"الرجاء الموافقة على الشروط لإكمال العمليّة.\";s:16:\"invalid_required\";s:49:\"الرجاء أكمل الحقول الناقصة\";s:12:\"invalid_date\";s:51:\"صيغة التاريخ تبدو غير صحيحة.\";s:14:\"date_too_early\";s:33:\"التاريخ مبكر جداً.\";s:13:\"date_too_late\";s:33:\"التاريخ بعيد جداً.\";s:17:\"captcha_not_match\";s:43:\"لقد قمت بإدخال كود خاطئ.\";s:14:\"invalid_number\";s:46:\"الرقم أصغر من الحد الأدنى\";s:16:\"number_too_small\";s:28:\"الرقم صغير جداً\";s:16:\"number_too_large\";s:29:\"الرقم كبير جداً.\";s:13:\"upload_failed\";s:29:\"فشل في رفع الملف\";s:24:\"upload_file_type_invalid\";s:60:\"هذا النوع من الملفات غير مسموح به\";s:21:\"upload_file_too_large\";s:35:\"هذا الملف كبير جداً\";s:23:\"upload_failed_php_error\";s:30:\"خطأ في رفع الملف.\";s:23:\"quiz_answer_not_correct\";s:31:\"إجابتك غير صحيحة.\";s:13:\"invalid_email\";s:56:\"يبدو أن البريد الإلكتروني خاطئ\";s:11:\"invalid_url\";s:42:\"يبدو أن الرابط غير صحيح\";s:11:\"invalid_tel\";s:49:\"يبدو أن رقم الهاتف غير صحيح\";}'),
