-- --------------------------------------------------------

--
-- Structure de la table `wp2_posts`
--

CREATE TABLE `wp2_posts` (
  `ID` bigint UNSIGNED NOT NULL,
  `post_author` bigint UNSIGNED NOT NULL DEFAULT '0',
  `post_date` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_date_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content` longtext NOT NULL,
  `post_title` text NOT NULL,
  `post_excerpt` text NOT NULL,
  `post_status` varchar(20) NOT NULL DEFAULT 'publish',
  `comment_status` varchar(20) NOT NULL DEFAULT 'open',
  `ping_status` varchar(20) NOT NULL DEFAULT 'open',
  `post_password` varchar(20) NOT NULL DEFAULT '',
  `post_name` varchar(200) NOT NULL DEFAULT '',
  `to_ping` text NOT NULL,
  `pinged` text NOT NULL,
  `post_modified` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_modified_gmt` datetime NOT NULL DEFAULT '0000-00-00 00:00:00',
  `post_content_filtered` longtext NOT NULL,
  `post_parent` bigint UNSIGNED NOT NULL DEFAULT '0',
  `guid` varchar(255) NOT NULL DEFAULT '',
  `menu_order` int NOT NULL DEFAULT '0',
  `post_type` varchar(20) NOT NULL DEFAULT 'post',
  `post_mime_type` varchar(100) NOT NULL DEFAULT '',
  `comment_count` bigint NOT NULL DEFAULT '0'
) ENGINE=MyISAM DEFAULT CHARSET=utf8mb3;

--
-- Déchargement des données de la table `wp2_posts`
--

INSERT INTO `wp2_posts` (`ID`, `post_author`, `post_date`, `post_date_gmt`, `post_content`, `post_title`, `post_excerpt`, `post_status`, `comment_status`, `ping_status`, `post_password`, `post_name`, `to_ping`, `pinged`, `post_modified`, `post_modified_gmt`, `post_content_filtered`, `post_parent`, `guid`, `menu_order`, `post_type`, `post_mime_type`, `comment_count`) VALUES
(1, 1, '2013-08-01 21:41:43', '2013-08-01 21:41:43', 'مرحباً بك في ووردبريس. هذه تدوينتك الأولى. حررها أو احذفها، ثم ابدأ بالتدوين!\nاذا احتجت لمساعدة يمكنك زيارة موقع <a href=\"http://www.ar-wp.com/\">عرب ووردبريس</a> - الدعم الفني باللغة العربية.\n\n ', 'أهلاً بالعالم !', '', 'publish', 'open', 'open', '', '%d8%a3%d9%87%d9%84%d8%a7-%d8%a8%d8%a7%d9%84%d8%b9%d8%a7%d9%84%d9%85', '', '', '2013-08-01 21:41:43', '2013-08-01 21:41:43', '', 0, 'http://www.ibn-sinaa.com/wp/?p=1', 0, 'post', '', 1),
(2, 1, '2013-08-01 21:41:43', '2013-08-01 21:41:43', 'هنا تشاهد مثال على صفحة. الصفحة تختلف عن التدوينة لأنها تبقى ثابتة وتظهر عادةً في أغلب القوالب ضمن قوائم التصفّح. مفضّل أن تبدأ بإنشاء صفحة جديدة تسميها مثلاً (سيرة ذاتية) أو (من نحن) بحيث تظهر فيها معلومات عامة عن مالك الموقع. لنشاهد مثال على ذلك:\n\n<blockquote>مرحباً! اسمي محمد. وُلدت في فلسطين عام 1980م وأعمل كمبرمج في إحدى الجامعات الرسمية في المملكة العربية السعودية. أقضي يومياً ساعات طويلة أمام شاشة الحاسوب. أحب الشعر وأهوى الخواطر ولدي قطة صغيرة أسميتها \"ميشو\" ... الخ  </blockquote>\n \nمثال آخر:\n \n<blockquote>شركة BVB تأسسّت عام 1909م وهي شركة عالمية متخصّصة بإنتاج المخصبات الزراعية والأسمدة العضوية والمعدنية. مقّر الشركة في ألمانيا ويعمل لدينا أكثر من 88000 موظّف. تتمركز نشاطات الشركة في منطقة وسط أوروبا ... الخ</blockquote>\n \nكمستخدم جديد لنظام ووردبريس عليك التوجّه إلى <a href=\"http://www.ibn-sinaa.com/wp/wp-admin/\">لوحة التحكم</a> لحذف هذه الصفحة وإنشاء صفحة أو صفحات جديدة تكتب فيها ما تراه مناسباً لك. نتمنى لك التوفيق!', 'مثال على صفحة', '', 'publish', 'open', 'open', '', 'مثال-على-صفحة', '', '', '2013-08-01 21:41:43', '2013-08-01 21:41:43', '', 0, 'http://www.ibn-sinaa.com/wp/?page_id=2', 0, 'page', '', 0),
